1	import {
2	  CallHandler,
3	  CanActivate,
4	  Controller,
5	  ExecutionContext,
6	  Get,
7	  INestApplication,
8	  Injectable,
9	  Module,
10	  NestInterceptor,
11	  Observable,
12	  PipeTransform,
13	  Query,
14	} from '@nestjs/common';
15	import { NestFactory } from '@nestjs/core';
16	import {
17	  FastifyAdapter,
18	  NestFastifyApplication,
19	} from '@nestjs/platform-fastify';
20	import * as http from 'http';
21	import * as net from 'net';
22	import { AppModule } from '../src/app.module.js';
23	import { appCounters, resetAppCounters } from '../src/app.controller.js';
24	
25	interface RawResponse {
26	  status: number;
27	  headers: http.IncomingHttpHeaders;
28	  body: string;
29	}
30	
31	const request = (
32	  port: number,
33	  path: string,
34	  agent?: http.Agent,
35	): Promise<RawResponse> =>
36	  new Promise<RawResponse>((resolve, reject) => {
37	    http
38	      .get(
39	        `http://localhost:${port}${path}`,
40	        agent
41	          ? { agent }
42	          : {
43	              // Explicitly close connection after response to speed up server shutdown
44	              headers: { Connection: 'close' },
45	            },
46	        res => {
47	          let body = '';
48	          res.on('data', chunk => (body += chunk));
49	          res.on('end', () =>
50	            resolve({
51	              status: res.statusCode || 0,
52	              headers: res.headers,
53	              body,
54	            }),
55	          );
56	        },
57	      )
58	      .on('error', reject);
59	  });
60	
61	const counters = {
62	  guard: 0,
63	  pipe: 0,
64	  interceptor: 0,
65	  handler: 0,
66	};
67	
68	@Injectable()
69	class CountingGuard implements CanActivate {
70	  canActivate() {
71	    counters.guard++;
72	    return true;
73	  }
74	}
75	
76	@Injectable()
77	class CountingPipe implements PipeTransform {
78	  transform(value: unknown) {
79	    counters.pipe++;
80	    return value;
81	  }
82	}
83	
84	@Injectable()
85	class CountingInterceptor implements NestInterceptor {
86	  intercept(_context: ExecutionContext, next: CallHandler): Observable<any> {
87	    counters.interceptor++;
88	    return next.handle();
89	  }
90	}
91	
92	@Controller()
93	class SideEffectController {
94	  @Get('slow')
95	  async slow(@Query('q', CountingPipe) _q?: string) {
96	    counters.handler++;
97	    // Simulate work
98	    await new Promise(resolve => setTimeout(resolve, 500));
99	    return 'ok';
100	  }
101	
102	  @Get('boom')
103	  async boom() {
104	    await new Promise(resolve => setTimeout(resolve, 100));
105	    throw new Error('boom');
106	  }
107	}
108	
109	@Module({
110	  controllers: [SideEffectController],
111	})
112	class SideEffectModule {}
113	
114	describe('Graceful Shutdown (Fastify)', () => {
115	  let app: INestApplication;
116	
117	  afterEach(async () => {
118	    if (app) {
119	      await app.close();
120	    }
121	  });
122	
123	  it('should allow in-flight requests to complete when return503OnClosing is enabled', async () => {
124	    app = await NestFactory.create<NestFastifyApplication>(
125	      AppModule,
126	      new FastifyAdapter(),
127	      {
128	        return503OnClosing: true,
129	        logger: false,
130	      },
131	    );
132	    await app.listen(0);
133	    const port = app.getHttpServer().address().port;
134	
135	    const requestPromise = request(port, '/slow');
136	
137	    // Wait to ensure request is processing
138	    await new Promise(r => setTimeout(r, 100));
139	
140	    const closePromise = app.close();
141	
142	    // The in-flight request should finish successfully
143	    const response = await requestPromise;
144	    expect(response.status).toBe(200);
145	    expect(response.body).toBe('ok');
146	
147	    await closePromise;
148	  }, 10000);
149	
150	  it('should return 503 for NEW queued requests on existing connections during shutdown', async () => {
151	    app = await NestFactory.create<NestFastifyApplication>(
152	      AppModule,
153	      new FastifyAdapter(),
154	      {
155	        return503OnClosing: true,
156	        logger: false,
157	      },
158	    );
159	    await app.listen(0);
160	    const port = app.getHttpServer().address().port;
161	
162	    // Force 1 socket to ensure queuing/reuse
163	    const agent = new http.Agent({ keepAlive: true, maxSockets: 1 });
164	
165	    // 1. Send Request A (slow) - occupies the socket
166	    const requestA = request(port, '/slow', agent);
167	
168	    // 2. Wait so Request A is definitely "in flight"
169	    await new Promise(r => setTimeout(r, 100));
170	
171	    // 3. Trigger Shutdown (don't await yet)
172	    const closePromise = app.close();
173	
174	    // Allow the microtask for prepareClose() to flush (sets isShuttingDown)
175	    await new Promise(r => setTimeout(r, 0));
176	
177	    // 4. Send Request B immediately using the same agent.
178	    const requestB = request(port, '/slow', agent);
179	
180	    const responseA = await requestA;
181	    expect(responseA.status).toBe(200);
182	    expect(responseA.body).toBe('ok');
183	
184	    const responseB = await requestB;
185	    expect(responseB.status).toBe(503);
186	    expect(responseB.body).toBe('Service Unavailable');
187	    expect(responseB.headers['connection']).toBe('close');
188	
189	    await closePromise;
190	    agent.destroy();
191	  }, 10000);
192	
193	  it('should reject post-shutdown requests before guards, pipes, interceptors and handlers run', async () => {
194	    counters.guard = 0;
195	    counters.pipe = 0;
196	    counters.interceptor = 0;
197	    counters.handler = 0;
198	
199	    app = await NestFactory.create<NestFastifyApplication>(
200	      SideEffectModule,
201	      new FastifyAdapter(),
202	      {
203	        return503OnClosing: true,
204	        logger: false,
205	      },
206	    );
207	    app.useGlobalGuards(new CountingGuard());
208	    app.useGlobalInterceptors(new CountingInterceptor());
209	    await app.listen(0);
210	    const port = app.getHttpServer().address().port;
211	
212	    const agent = new http.Agent({ keepAlive: true, maxSockets: 1 });
213	
214	    // Request A (slow) occupies the only socket
215	    const requestA = request(port, '/slow?q=1', agent);
216	    await new Promise(r => setTimeout(r, 100));
217	
218	    const closePromise = app.close();
219	    await new Promise(r => setTimeout(r, 0));
220	
221	    // Request B is queued on the same connection and arrives after the
222	    // shutdown state has been established
223	    const requestB = request(port, '/slow?q=2', agent);
224	
225	    const responseA = await requestA;
226	    expect(responseA.status).toBe(200);
227	
228	    const responseB = await requestB;
229	    expect(responseB.status).toBe(503);
230	    expect(responseB.body).toBe('Service Unavailable');
231	    expect(responseB.headers['connection']).toBe('close');
232	
233	    await closePromise;
234	
235	    // Only request A was allowed into the Nest pipeline
236	    expect(counters.guard).toBe(1);
237	    expect(counters.pipe).toBe(1);
238	    expect(counters.interceptor).toBe(1);
239	    expect(counters.handler).toBe(1);
240	
241	    agent.destroy();
242	  }, 10000);
243	
244	  it('should finish closing when an in-flight request throws', async () => {
245	    app = await NestFactory.create<NestFastifyApplication>(
246	      SideEffectModule,
247	      new FastifyAdapter(),
248	      {
249	        return503OnClosing: true,
250	        logger: false,
251	      },
252	    );
253	    await app.listen(0);
254	    const port = app.getHttpServer().address().port;
255	
256	    const requestPromise = request(port, '/boom');
257	    await new Promise(r => setTimeout(r, 20));
258	
259	    const closePromise = app.close();
260	
261	    const response = await requestPromise;
262	    expect(response.status).toBe(500);
263	
264	    await closePromise;
265	  }, 10000);
266	
267	  it('should finish closing when the client aborts an in-flight request', async () => {
268	    app = await NestFactory.create<NestFastifyApplication>(
269	      AppModule,
270	      new FastifyAdapter(),
271	      {
272	        return503OnClosing: true,
273	        logger: false,
274	      },
275	    );
276	    await app.listen(0);
277	    const port = app.getHttpServer().address().port;
278	
279	    const req = http.get(`http://localhost:${port}/slow`);
280	    req.on('error', () => {});
281	    await new Promise(r => setTimeout(r, 100));
282	
283	    // Abort the in-flight request, then shut down
284	    req.destroy();
285	
286	    await app.close();
287	  }, 10000);
288	
289	  it('should be idempotent across repeated close() calls', async () => {
290	    app = await NestFactory.create<NestFastifyApplication>(
291	      AppModule,
292	      new FastifyAdapter(),
293	      {
294	        return503OnClosing: true,
295	        logger: false,
296	      },
297	    );
298	    await app.listen(0);
299	
300	    await app.close();
301	    await expect(app.close()).resolves.toBeUndefined();
302	  }, 10000);
303	
304	  it('should enable the gate via the FastifyAdapter "return503OnClosing" option', async () => {
305	    app = await NestFactory.create<NestFastifyApplication>(
306	      AppModule,
307	      new FastifyAdapter({ return503OnClosing: true }),
308	      {
309	        logger: false,
310	      },
311	    );
312	    await app.listen(0);
313	    const port = app.getHttpServer().address().port;
314	
315	    const agent = new http.Agent({ keepAlive: true, maxSockets: 1 });
316	
317	    // Request A (slow) occupies the only socket
318	    const requestA = request(port, '/slow', agent);
319	    await new Promise(r => setTimeout(r, 100));
320	
321	    const closePromise = app.close();
322	    await new Promise(r => setTimeout(r, 0));
323	
324	    // Request B is queued on the same connection and arrives after the
325	    // shutdown state has been established
326	    const requestB = request(port, '/slow', agent);
327	
328	    const responseA = await requestA;
329	    expect(responseA.status).toBe(200);
330	    expect(responseA.body).toBe('ok');
331	
332	    const responseB = await requestB;
333	    expect(responseB.status).toBe(503);
334	    expect(responseB.body).toBe('Service Unavailable');
335	    expect(responseB.headers['connection']).toBe('close');
336	
337	    await closePromise;
338	    agent.destroy();
339	  }, 10000);
340	
341	  it('should reject a request whose body completes after shutdown started, without side effects', async () => {
342	    resetAppCounters();
343	
344	    app = await NestFactory.create<NestFastifyApplication>(
345	      AppModule,
346	      new FastifyAdapter({ return503OnClosing: true }),
347	      {
348	        logger: false,
349	      },
350	    );
351	    await app.listen(0);
352	    const port = app.getHttpServer().address().port;
353	
354	    const socket = net.createConnection(port, '127.0.0.1');
355	    socket.on('error', () => {});
356	    await new Promise<void>(resolve => socket.once('connect', resolve));
357	
358	    const body = JSON.stringify({ hello: 'world' });
359	    socket.write(
360	      `POST /echo HTTP/1.1\r\nHost: localhost:${port}\r\nContent-Type: application/json\r\nContent-Length: ${Buffer.byteLength(body)}\r\n\r\n`,
361	    );
362	    // Only the first chunk of the body goes out before the shutdown starts
363	    socket.write(body.slice(0, 5));
364	    await new Promise(r => setTimeout(r, 50));
365	
