165	  private onRequestHook?: (
166	    request: TRequest,
167	    reply: TReply,
168	    done: (err?: Error) => void,
169	  ) => void | Promise<void>;
170	  private onResponseHook?: (
171	    request: TRequest,
172	    reply: TReply,
173	    done: (err?: Error) => void,
174	  ) => void | Promise<void>;
175	  private isMiddieRegistered: boolean;
176	  private pendingMiddlewares: Array<{ args: any[] }> = [];
