181	  private readonly versionConstraint = {
182	    name: 'version',
183	    validate(value: unknown) {
184	      if (!isString(value) && !Array.isArray(value)) {
185	        throw new Error(
186	          'Version constraint should be a string or an array of strings.',
187	        );
188	      }
189	    },
190	    storage() {
191	      const versions = new Map<string, unknown>();
192	      return {
193	        get(version: string | Array<string>) {
194	          if (Array.isArray(version)) {
195	            return versions.get(version.find(v => versions.has(v))!) || null;
196	          }
197	          return versions.get(version) || null;
198	        },
199	        set(versionOrVersions: string | Array<string>, store: unknown) {
200	          const storeVersionConstraint = (version: string) =>
201	            versions.set(version, store);
202	          if (Array.isArray(versionOrVersions))
203	            versionOrVersions.forEach(storeVersionConstraint);
204	          else storeVersionConstraint(versionOrVersions);
205	        },
206	        del(version: string | Array<string>) {
207	          if (Array.isArray(version)) {
208	            version.forEach(v => versions.delete(v));
209	          } else {
210	            versions.delete(version);
211	          }
212	        },
213	        empty() {
214	          versions.clear();
215	        },
216	      };
217	    },
218	    deriveConstraint: (req: FastifyRequest) => {
219	      // Media Type (Accept Header) Versioning Handler
220	      if (this.versioningOptions?.type === VersioningType.MEDIA_TYPE) {
221	        const MEDIA_TYPE_HEADER = 'Accept';
222	        const acceptHeaderValue: string | undefined = (req.headers?.[
223	          MEDIA_TYPE_HEADER
224	        ] || req.headers?.[MEDIA_TYPE_HEADER.toLowerCase()]) as string;
225	
226	        const acceptHeaderVersionParameter = acceptHeaderValue
227	          ? acceptHeaderValue.split(';')[1]
228	          : undefined;
229	
230	        return isUndefined(acceptHeaderVersionParameter)
231	          ? VERSION_NEUTRAL // No version was supplied
232	          : acceptHeaderVersionParameter.split(this.versioningOptions.key)[1];
233	      }
234	      // Header Versioning Handler
235	      else if (this.versioningOptions?.type === VersioningType.HEADER) {
236	        const customHeaderVersionParameter: string | string[] | undefined =
237	          req.headers?.[this.versioningOptions.header] ||
238	          req.headers?.[this.versioningOptions.header.toLowerCase()];
239	
240	        return isUndefined(customHeaderVersionParameter)
241	          ? VERSION_NEUTRAL // No version was supplied
242	          : customHeaderVersionParameter;
243	      }
244	      // Custom Versioning Handler
245	      else if (this.versioningOptions?.type === VersioningType.CUSTOM) {
246	        return this.versioningOptions.extractor(req);
247	      }
248	      return undefined;
249	    },
250	    mustMatchWhenDerived: false,
251	  };
