823	  private isHttpFastifyError(
824	    error: any,
825	  ): error is Error & { statusCode: number } {
826	    // condition based on this code - https://github.com/fastify/fastify-error/blob/d669b150a82968322f9f7be992b2f6b463272de3/index.js#L22
827	    return (
828	      error.statusCode !== undefined &&
829	      error instanceof Error &&
830	      error.name === 'FastifyError'
831	    );
