834	  protected registerWithPrefix(
835	    factory:
836	      | FastifyPluginCallback<any>
837	      | FastifyPluginAsync<any>
838	      | Promise<{ default: FastifyPluginCallback<any> }>
839	      | Promise<{ default: FastifyPluginAsync<any> }>,
840	    prefix = '/',
841	  ) {
