947	
948	    this.useBodyParser(
949	      contentType,
950	      withRawBody,
951	      { bodyLimit },
952	      (_req, body, done) => {
953	        done(null, querystringParse(body.toString()));
954	      },
955	    );
956	  }
957	
958	  private async registerMiddie() {
959	    this.isMiddieRegistered = true;
960	    await this.register(
961	      middie as unknown as Parameters<TInstance['register']>[0],
962	    );
963	  }
964	
965	  private getRequestOriginalUrl(rawRequest: TRawRequest) {
966	    return rawRequest.originalUrl || rawRequest.url!;
967	  }
968	
969	  private injectRouteOptions(
970	    routerMethodKey: Uppercase<HTTPMethods>,
971	    ...args: any[]
972	  ) {
973	    const handlerRef = args[args.length - 1];
974	    const isVersioned =
975	      !isUndefined(handlerRef.version) &&
976	      handlerRef.version !== VERSION_NEUTRAL;
977	    const routeConfig = Reflect.getMetadata(
978	      FASTIFY_ROUTE_CONFIG_METADATA,
979	      handlerRef,
980	    );
981	
982	    const routeConstraints = Reflect.getMetadata(
983	      FASTIFY_ROUTE_CONSTRAINTS_METADATA,
984	      handlerRef,
985	    );
986	
987	    const routeSchema = Reflect.getMetadata(
988	      FASTIFY_ROUTE_SCHEMA_METADATA,
989	      handlerRef,
990	    );
991	
992	    const hasConfig = !isUndefined(routeConfig);
993	    const hasConstraints = !isUndefined(routeConstraints);
994	    const hasSchema = !isUndefined(routeSchema);
995	    const routeToInject: RouteOptions<TServer, TRawRequest, TRawResponse> &
996	      RouteShorthandOptions = {
997	      method: routerMethodKey,
998	      url: args[0],
999	      handler: handlerRef,
1000	    };
1001	
1002	    if (!this.instance.supportedMethods.includes(routerMethodKey)) {
1003	      this.instance.addHttpMethod(routerMethodKey, { hasBody: true });
1004	    }
1005	
1006	    if (isVersioned || hasConstraints || hasConfig || hasSchema) {
1007	      const isPathAndRouteTuple = args.length === 2;
1008	      if (isPathAndRouteTuple) {
1009	        const constraints = {
1010	          ...(hasConstraints && routeConstraints),
1011	          ...(isVersioned && {
1012	            version: handlerRef.version,
1013	          }),
1014	        };
1015	
1016	        const options = {
1017	          constraints,
1018	          ...(hasConfig && {
1019	            config: {
1020	              ...routeConfig,
1021	            },
1022	          }),
1023	          ...(hasSchema && {
1024	            schema: routeSchema,
1025	          }),
1026	        };
1027	
1028	        const routeToInjectWithOptions = { ...routeToInject, ...options };
1029	
1030	        return this.instance.route(routeToInjectWithOptions);
1031	      }
1032	    }
1033	    return this.instance.route(routeToInject);
1034	  }
1035	
1036	  /**
1037	   * Fastify still accepts the router options ("ignoreTrailingSlash",
1038	   * "caseSensitive", ...) at the top level, but "initialConfig.routerOptions"
1039	   * only reflects them when they are passed through "routerOptions". As the
1040	   * adapter always passes "routerOptions" (for the version constraint), the
1041	   * top-level values are folded in so that plugins relying on
1042	   * "initialConfig.routerOptions" (like @fastify/middie) normalize request
1043	   * paths exactly like the router does.
1044	   */
1045	  private getTopLevelRouterOptions(
1046	    options?: FastifyServerOptions,
1047	  ): NonNullable<FastifyServerOptions['routerOptions']> {
1048	    const routerOptions: Record<string, unknown> = {};
1049	    const routerOptionKeys = [
1050	      'ignoreTrailingSlash',
1051	      'ignoreDuplicateSlashes',
1052	      'caseSensitive',
1053	      'useSemicolonDelimiter',
1054	      'maxParamLength',
1055	      'allowUnsafeRegex',
1056	    ] as const;
1057	    for (const key of routerOptionKeys) {
1058	      if (options?.[key] !== undefined) {
1059	        routerOptions[key] = options[key];
1060	      }
1061	    }
1062	    return routerOptions;
1063	  }
1064	
1065	  private sanitizeUrl(url: string): string {
1066	    const initialConfig = this.instance.initialConfig as FastifyServerOptions;
1067	    const routerOptions =
1068	      initialConfig.routerOptions as Partial<FastifyServerOptions>;
1069	
1070	    // Absolute-form request targets ("GET http://host/path HTTP/1.1") must be
1071	    // resolved to their path before any other normalization, as the Fastify
1072	    // router does, so that middleware and routes always match the same path.
1073	    url = this.getPathFromRequestTarget(url);
1074	
1075	    if (
1076	      routerOptions.ignoreDuplicateSlashes ||
1077	      initialConfig.ignoreDuplicateSlashes
1078	    ) {
1079	      url = this.removeDuplicateSlashes(url);
1080	    }
1081	
1082	    if (
1083	      routerOptions.ignoreTrailingSlash ||
1084	      initialConfig.ignoreTrailingSlash
1085	    ) {
1086	      url = this.trimLastSlash(url);
1087	    }
1088	
1089	    if (
1090	      routerOptions.caseSensitive === false ||
1091	      initialConfig.caseSensitive === false
1092	    ) {
1093	      url = url.toLowerCase();
1094	    }
1095	    return safeDecodeURI(
1096	      url,
1097	      routerOptions.useSemicolonDelimiter ||
1098	        initialConfig.useSemicolonDelimiter,
1099	    ).path;
1100	  }
1101	
1102	  private removeDuplicateSlashes(path: string) {
1103	    const REMOVE_DUPLICATE_SLASHES_REGEXP = /\/\/+/g;
1104	    return path.indexOf('//') !== -1
1105	      ? path.replace(REMOVE_DUPLICATE_SLASHES_REGEXP, '/')
1106	      : path;
1107	  }
1108	
1109	  private trimLastSlash(path: string) {
1110	    if (path.length > 1 && path.charCodeAt(path.length - 1) === 47) {
1111	      return path.slice(0, -1);
1112	    }
1113	    return path;
1114	  }
1115	
1116	  /**
1117	   * Mirrors the absolute-form request target handling of "find-my-way".
1118	   * Returns the path of an absolute-form target ("http://host/path" -> "/path")
1119	   * and leaves any other request target untouched.
1120	   */
1121	  private getPathFromRequestTarget(url: string): string {
1122	    if (url.charCodeAt(0) === 47 /* '/' */) {
1123	      return url;
1124	    }
1125	    const schemeEnd = url.indexOf('://');
1126	    if (schemeEnd === -1) {
1127	      return url;
1128	    }
1129	    const scheme = url.slice(0, schemeEnd).toLowerCase();
1130	    if (scheme !== 'http' && scheme !== 'https') {
1131	      return url;
1132	    }
1133	    const authorityStart = schemeEnd + 3;
1134	    const pathStart = url.indexOf('/', authorityStart);
1135	    if (pathStart === authorityStart || !URL.canParse(url)) {
1136	      // Malformed target: the router rejects it before any middleware runs
1137	      return url;
1138	    }
1139	    return pathStart === -1 ? '/' : url.slice(pathStart);
1140	  }
1141	}
