import { INestApplication } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import {
  FastifyAdapter,
  NestFastifyApplication,
} from '@nestjs/platform-fastify';
import * as http from 'http';
import { AppModule } from './app.module.js';
import { appCounters, resetAppCounters } from './app.controller.js';

const request = (port: number, path: string): Promise<any> =>
  new Promise((resolve, reject) => {
    http
      .get(
        `http://localhost:${port}${path}`,
        { headers: { Connection: 'close' } },
        res => {
          let body = '';
          res.on('data', chunk => (body += chunk));
          res.on('end', () =>
            resolve({ status: res.statusCode, body, headers: res.headers }),
          );
        },
      )
      .on('error', reject);
  });

describe('scratch', () => {
  let app: INestApplication;

  afterEach(async () => {
    try {
      await app?.close();
    } catch {}
  });

  it('sequential close calls run cleanup once', async () => {
    resetAppCounters();
    app = await NestFactory.create<NestFastifyApplication>(
      AppModule,
      new FastifyAdapter({ return503OnClosing: true }),
      { logger: false },
    );
    await app.listen(0);
    await app.close();
    await app.close();
    console.log('cleanupCount after 2 sequential closes:', appCounters.cleanupCount);
  });

  it('stats after close', async () => {
    resetAppCounters();
    app = await NestFactory.create<NestFastifyApplication>(
      AppModule,
      new FastifyAdapter({ return503OnClosing: true }),
      { logger: false },
    );
    await app.listen(0);
    const port = app.getHttpServer().address().port;
    const r = await request(port, '/graceful-probe?mode=stats');
    console.log('stats status/body:', r.status, r.body);
    await app.close();
  });
});

