import { INestApplication } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import {
  FastifyAdapter,
  NestFastifyApplication,
} from '@nestjs/platform-fastify';
import * as http from 'http';
import { AppModule } from '../src/app.module.js';

describe('scratch2', () => {
  let app: INestApplication;

  afterEach(async () => {
    try {
      await app?.close();
    } catch {}
  });

  it('close drains in-flight on keep-alive then resolves promptly', async () => {
    app = await NestFactory.create<NestFastifyApplication>(
      AppModule,
      new FastifyAdapter({ return503OnClosing: true }),
      { logger: false },
    );
    await app.listen(0);
    const port = app.getHttpServer().address().port;

    const agent = new http.Agent({ keepAlive: true, maxSockets: 1 });
    const responsePromise = new Promise<any>((resolve, reject) => {
      http
        .get(`http://localhost:${port}/slow?delay=300`, { agent }, res => {
          let body = '';
          res.on('data', c => (body += c));
          res.on('end', () =>
            resolve({ status: res.statusCode, headers: res.headers, body }),
          );
        })
        .on('error', reject);
    });
    await new Promise(r => setTimeout(r, 100));

    const t0 = Date.now();
    await app.close();
    console.log('close resolved in', Date.now() - t0, 'ms');
    const res = await responsePromise;
    console.log('response', res.status, res.headers.connection, res.body);
    agent.destroy();
  }, 15000);
});

