const http = require('http');

const server = http.createServer((req, res) => {
  console.log('REQUEST EVENT:', req.method, req.url, 'at', Date.now() - t0, 'ms');
  let body = '';
  req.on('data', c => (body += c));
  req.on('end', () => {
    console.log('  body end:', JSON.stringify(body), 'at', Date.now() - t0);
    if (req.url === '/slow') {
      setTimeout(() => {
        res.end('ok');
      }, 300);
    } else {
      res.end('echo:' + body);
    }
  });
});

const t0 = Date.now();
server.listen(0, '127.0.0.1', () => {
  const port = server.address().port;
  const net = require('net');
  const socket = net.connect(port, '127.0.0.1', () => {
    // Request A: POST with full content-length but send only part of body
    socket.write(
      'POST /echo HTTP/1.1\r\nHost: x\r\nContent-Length: 13\r\n\r\nhello',
    );
    console.log('sent A head+5 bytes at', Date.now() - t0);
    // Pipeline request B fully before A's body completes
    socket.write('GET /slow HTTP/1.1\r\nHost: x\r\n\r\n');
    console.log('pipelined B at', Date.now() - t0);

    setTimeout(() => {
      socket.write(' world');
      console.log('completed A body at', Date.now() - t0);
    }, 200);

    setTimeout(() => {
      let data = '';
      socket.on('data', d => {
        data += d.toString().split('\r\n')[0];
        console.log('RESP:', d.toString().split('\r\n')[0]);
      });
    }, 0);

    setTimeout(() => {
      server.close();
      socket.destroy();
      process.exit(0);
    }, 800);
  });
});

