/**
 * Installs a request gate in front of Fastify's routing so that, once the
 * shutdown has started, new requests are rejected with
 * "503 Service Unavailable" before they can enter the Nest pipeline
 * (middleware, guards, pipes, interceptors, handlers), while requests
 * that were already accepted run to completion.
 *
 * The gate has two layers:
 *
 * - a wrapper around the server's "request" listener, which rejects every
 *   request whose headers arrive after the shutdown started — including
 *   requests pipelined on an existing keep-alive connection and new HTTP/2
 *   streams multiplexed over an existing session. The listener is wrapped
 *   instead of using a Fastify "onRequest" hook because Fastify's own
 *   "return503OnClosing" fast path (enabled by default) runs before any
 *   hook and answers with a JSON body, which would not match the
 *   Express-compatible contract (a plain "Service Unavailable" body and,
 *   for HTTP/1.1, a "Connection: close" header — HTTP/2 forbids the
 *   connection-specific header, so it is omitted for streams);
 * - a "preHandler" hook, which covers requests that were accepted by the
 *   first layer while the application was still running but have not
 *   reached a route handler yet when the shutdown starts — most notably
 *   requests whose body is still streaming in. Fastify runs "preHandler"
 *   hooks after the request body has been fully received and right before
 *   the route handler (where the Nest pipeline begins), so a late
 *   rejection here still happens before any guard, pipe, interceptor or
 *   controller runs and cannot trigger business side effects.
 *
 * Every admitted request is also tracked so that "close()" can wait for
 * all in-flight requests — including HTTP/2 streams sharing a session —
 * to settle before the underlying servers are torn down.
 */
private installClosingRequestGate() {
  this.isClosingRequestGateEnabled = true;
  const routing = this.instance.routing;
  for (const server of this.getRequestHandlerServers()) {
    server.removeListener('request', routing);
    server.on('request', (req, res) => {
      if (!this.isShuttingDown) {
        this.trackInflightRequest(
          req as unknown as TRawRequest,
          res as unknown as TRawResponse,
        );
        routing(
          req as unknown as TRawRequest,
          res as unknown as TRawResponse,
        );
        return;
      }
      this.respondServiceUnavailable(
        req as unknown as TRawRequest,
        res as unknown as TRawResponse,
      );
    });
  }

  this.instance.addHook('preHandler', (request, reply, done) => {
    const tracker = this.inflightRequests.get(
      request.raw as unknown as TRawRequest,
    );
    if (tracker) {
      tracker.enteredHandler = true;
    }
    if (!this.isShuttingDown) {
      done();
      return;
    }
    if (request.raw.httpVersionMajor !== 2) {
      reply.header('Connection', 'close');
    }
    // Short-circuit the lifecycle without calling "done()".
    reply
      .code(HttpStatus.SERVICE_UNAVAILABLE)
      .header('Content-Type', 'text/plain')
      .send('Service Unavailable');
  });
}

/**
 * Installs in-flight request tracking without the 503 rejection logic;
 * used together with the HTTP/2 + HTTP/1.1 demultiplexing when the closing
 * request gate itself is not enabled.
 */
private installInflightRequestTracking() {
  const routing = this.instance.routing;
  for (const server of this.getRequestHandlerServers()) {
    server.removeListener('request', routing);
    server.on('request', (req, res) => {
      this.trackInflightRequest(
        req as unknown as TRawRequest,
        res as unknown as TRawResponse,
      );
      routing(req as unknown as TRawRequest, res as unknown as TRawResponse);
    });
  }
}

/**
 * Tracks a request that was allowed into the Fastify lifecycle so that
 * "close()" can wait for every in-flight request to settle before the
 * underlying servers are closed and HTTP/2 sessions are asked to end.
 */
private trackInflightRequest(req: TRawRequest, res: TRawResponse) {
  this.inflightRequests.set(req, { res, enteredHandler: false });
  (res as unknown as http.ServerResponse).once('close', () => {
    this.inflightRequests.delete(req);
    if (this.inflightRequests.size === 0) {
      this.onInflightRequestsDrained?.();
    }
  });
}

/**
 * Resolves once every request admitted so far has settled. Resolves
 * immediately when no request is in flight (or none is tracked).
 */
private waitForInflightRequestsToDrain(): Promise<void> {
  if (this.inflightRequests.size === 0) {
    return Promise.resolve();
  }
