private async closeInstance(): Promise<void> {
  if (this.isClosingRequestGateEnabled) {
    // Requests that were admitted before the shutdown started but have not
    // crossed into the route handler chain (their body is still streaming
    // in, or pre-handler hooks are pending) never become business work:
    // end their connections now instead of waiting for bytes that may
    // never arrive. Requests that already entered a handler are left alone
    // and awaited below so they finish with their full business result.
    for (const state of this.inflightRequests.values()) {
      if (!state.enteredHandler) {
        this.destroyResponseConnection(state.res);
      }
    }
    await this.waitForInflightRequestsToDrain();
  }

  try {
    await this.instance.close();
  } catch (err) {
    // Check if server is still running
    if (err.code !== 'ERR_SERVER_NOT_RUNNING') {
      throw err;
    }
  }
}

