public async close(signal?: string): Promise<void> {
  if (this.isClosed) {
    return;
  }
  this.activeClosePromise ??= super
    .close(signal)
    .then(() => {
      this.isClosed = true;
    })
    .finally(() => {
      this.activeClosePromise = undefined;
    });
