protected registerWithPrefix(
  factory:
    | FastifyPluginCallback<any>
    | FastifyPluginAsync<any>
    | Promise<{ default: FastifyPluginCallback<any> }>
    | Promise<{ default: FastifyPluginAsync<any> }>,
  prefix = '/',
) {
  return this.instance.register(factory, { prefix });
}

private isNativeResponse(
  response: TRawResponse | TReply,
): response is TRawResponse {
  return !('status' in response);
}

private async closeInstance(): Promise<void> {
  try {
    if (this.requiresInflightDrain()) {
      if (this.isClosingRequestGateEnabled) {
        // Reject requests that were accepted before the shutdown started
        // but have not reached a route handler yet (e.g. their body is
        // still streaming in). Letting them run would either leak them
        // into the business pipeline or — for HTTP/2 streams whose body
        // never completes — block the drain below forever.
        this.rejectRequestsNotYetInHandler();
      }
      if (this.isHttp2WithHttp1Fallback) {
        // Reap the HTTP/1.1 fallback connections that are idle right now
        // (in-flight ones are spared and drained below), mirroring the
        // timing of Fastify's own "closeIdleConnections".
        for (const server of this.http1FallbackServers) {
          server.closeIdleConnections();
        }
      }
      // Let every in-flight request (above all HTTP/2 streams multiplexed
      // over shared sessions) settle before the underlying servers are
      // closed. Closing an HTTP/2 server asks its sessions to end right
      // away; doing so while requests are still in flight would cut them
      // off and would prevent the closing request gate from answering
      // late streams with 503.
      await this.waitForInflightRequestsToDrain();
      await this.releaseHttp2SessionsAndConnections();
    }
    await this.instance.close();
  } catch (err) {
    // Check if server is still running
    if (err.code !== 'ERR_SERVER_NOT_RUNNING') {
      throw err;
    }
  }
}

/**
 * Whether "close()" has to drain in-flight requests itself before closing
 * the Fastify instance: needed for HTTP/2 servers (closing them ends the
 * multiplexed sessions right away) and for the HTTP/2 + HTTP/1.1
 * demultiplexing (the internal HTTP/1.1 fallback server never listens, so
 * its own "close()" would not wait for the connections injected into
 * it). Plain HTTP/1.1 servers are drained natively by "server.close()".
 */
private requiresInflightDrain(): boolean {
  if (this.isHttp2WithHttp1Fallback) {
    return true;
  }
  // The "http2" module does not export the server classes, so detect the
  // HTTP/2 servers Fastify created ("http2" option) by their class name.
  const constructorName = (this.httpServer as { constructor?: { name?: string } })
    ?.constructor?.name;
  return (
    constructorName === 'Http2Server' ||
    constructorName === 'Http2SecureServer'
  );
}

/**
 * The servers whose "request" listener is Fastify's routing function:
 * the Fastify server itself, or — when cleartext HTTP/2 with HTTP/1.1
 * fallback is enabled — the internal HTTP/2 and HTTP/1.1 servers the
 * demultiplexing server hands connections to.
 */
private getRequestHandlerServers(): Array<
  http.Server | http2.Http2Server
> {
  if (this.isHttp2WithHttp1Fallback) {
    return [...this.http2DemuxServers, ...this.http1FallbackServers];

