private async closeInstance(): Promise<void> {
  if (this.isClosingRequestGateEnabled) {
    // Requests admitted before the shutdown started that have not crossed
    // into the route handler chain yet (their body is still streaming in,
    // or pre-handler hooks are still pending) never become business work:
    // answer them with the shutdown response now. Requests that already
    // entered a handler are left alone and awaited below so they finish
    // with their full business result (success, error or client abort).
    this.rejectRequestsNotYetInHandler();
    await this.waitForInflightRequestsToDrain();
    // Fastify's own "closeIdleConnections" runs at the very beginning of
    // "instance.close()", when sockets still carrying an in-flight request
    // are active and therefore spared; once the request above settles the
    // socket turns idle and nothing reaps it anymore, which would keep
    // "server.close()" waiting until the keep-alive timeout even though
    // the response was already sent. Reap idle sockets again now that
    // every business request has settled.
    this.closeIdleConnections();
  }

  try {
    await this.instance.close();
  } catch (err) {
    // Check if server is still running
    if (err.code !== 'ERR_SERVER_NOT_RUNNING') {
      throw err;
    }
  }
}

/**
 * Closes keep-alive sockets that are idle after the in-flight requests
 * drained. Sockets that still carry a response being flushed (e.g. the
 * "Connection: close" 503 answer to a request pipelined behind the last
 * business request) are not idle and are left for Node to close once the
 * response has been written.
 */
private closeIdleConnections() {
  const server = this.httpServer as
    | (http.Server & { closeIdleConnections?: () => void })
    | undefined;
  server?.closeIdleConnections?.();
}

