import { FastifyAdapter, NestFastifyApplication } from '@nestjs/platform-fastify';
import * as http from 'http';
import { AppModule } from '../src/app.module.js';

describe('scratch timing', () => {
  let app: INestApplication;
  afterEach(async () => {
    try {
      await app?.close();
    } catch {}
  });

  it('measures close timing with keep-alive in-flight, no follow-up', async () => {
    app = await NestFactory.create<NestFastifyApplication>(
      AppModule,
      new FastifyAdapter({ return503OnClosing: true }),
      { logger: false },
    );
    await app.listen(0);
    const port = app.getHttpServer().address().port;
    const agent = new http.Agent({ keepAlive: true, maxSockets: 1 });
    const rp = new Promise<any>((resolve, reject) => {
      http
        .get(`http://localhost:${port}/slow?delay=300`, { agent }, res => {
          let body = '';
          res.on('data', c => (body += c));
          res.on('end', () => resolve({ status: res.statusCode, body }));
        })
        .on('error', reject);
    });
    await new Promise(r => setTimeout(r, 100));
    const t0 = Date.now();
    await app.close();
    console.log('NO_FOLLOWUP_CLOSE_MS', Date.now() - t0);
    const r = await rp;
    console.log('RESP', r.status, r.body);
    agent.destroy();
  }, 60000);
});

