import { INestApplication } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { FastifyAdapter, NestFastifyApplication } from '@nestjs/platform-fastify';
import * as http from 'http';
import { AppModule } from '../src/app.module.js';

describe('baseline timing', () => {
  let app: INestApplication;
  afterEach(async () => {
    try {
      await app?.close();
    } catch {}
  });

  for (const mode of ['connection-close', 'keepalive-hold', 'keepalive-destroy']) {
    it(mode, async () => {
      app = await NestFactory.create<NestFastifyApplication>(
        AppModule,
        new FastifyAdapter({ return503OnClosing: true }),
        { logger: false },
      );
      await app.listen(0);
      const server = app.getHttpServer() as http.Server;
      const port = server.address().port;
      const agent = new http.Agent({ keepAlive: mode !== 'connection-close', maxSockets: 1 });
      const headers: any = mode === 'connection-close' ? { Connection: 'close' } : {};
      const rp = new Promise<any>((resolve, reject) => {
        http.get(`http://localhost:${port}/slow?delay=300`, { agent, headers }, res => {
          let body = '';
          res.on('data', c => (body += c));
          res.on('end', () => resolve({ status: res.statusCode, body }));
        }).on('error', reject);
      });
      await new Promise(r => setTimeout(r, 100));
      const t0 = Date.now();
      const closeP = app.close().then(() => Date.now() - t0);
      if (mode === 'keepalive-destroy') {
        await rp;
        await new Promise(r => setTimeout(r, 20));
        agent.destroy();
      }
      const ms = await closeP;
      console.log(mode, 'CLOSE_MS', ms);
      await rp;
      agent.destroy();
    }, 60000);
  }
});

