  describe('close', () => {
    function createInstanceWithAdapter(adapter?: Partial<NoopHttpAdapter>) {
      const applicationConfig = new ApplicationConfig();
      const container = new NestContainer(applicationConfig);
      return new NestApplication(
        container,
        new NoopHttpAdapter({}),
        applicationConfig,
        new GraphInspector(container),
        {},
      );
    }

    it('runs the teardown only once across concurrent and repeated close() calls', async () => {
      const applicationConfig = new ApplicationConfig();
      const container = new NestContainer(applicationConfig);
      const adapter = new NoopHttpAdapter({});
      const closeSpy = vi.fn();
      adapter.close = closeSpy as any;
      const instance = new NestApplication(
        container,
        adapter,
        applicationConfig,
        new GraphInspector(container),
        {},
      );

      await Promise.all([instance.close(), instance.close()]);
      await instance.close();

      expect(closeSpy).toHaveBeenCalledTimes(1);
    });

    it('does not latch when the shutdown sequence fails', async () => {
      const applicationConfig = new ApplicationConfig();
      const container = new NestContainer(applicationConfig);
      const adapter = new NoopHttpAdapter({});
      const closeSpy = vi
        .fn()
        .mockRejectedValueOnce(new Error('boom'))
        .mockResolvedValue(undefined);
      adapter.close = closeSpy as any;
      const instance = new NestApplication(
        container,
        adapter,
        applicationConfig,
        new GraphInspector(container),
        {},
      );

      await expect(instance.close()).rejects.toThrow('boom');
      await instance.close();

      expect(closeSpy).toHaveBeenCalledTimes(2);
    });

    it('is a no-op once a shutdown completed successfully', async () => {
      const instance = createInstanceWithAdapter();
      const closeSpy = vi.fn();
      (instance.getHttpAdapter() as any);
      instance.getHttpAdapter = instance.getHttpAdapter.bind(instance);
      const adapter = (instance as any).httpAdapter as NoopHttpAdapter;
      adapter.close = closeSpy as any;

      await instance.close();
      await instance.close();

      expect(closeSpy).toHaveBeenCalledTimes(1);
    });
  });
});

